import { Input } from "./types.ts";
import {
  ImageAnnotations,
  PointsAnnotation,
  PointsAnnotationType,
  TextAnnotation,
  Color,
} from "@foxglove/schemas";

export const inputs = ["/sign_yolo/detections"];
export const output = "/sign_yolo/annotations";

function lampStyle(cls: string): { name: string; color: Color; bg: Color } {
  if (cls === "1" || cls === "sign_tower_R") {
    return {
      name: "RED",
      color: { r: 1.0, g: 0.22, b: 0.22, a: 1.0 },
      bg: { r: 0.35, g: 0.04, b: 0.04, a: 0.85 },
    };
  }
  if (cls === "2" || cls === "sign_tower_Y") {
    return {
      name: "YELLOW",
      color: { r: 1.0, g: 0.88, b: 0.15, a: 1.0 },
      bg: { r: 0.35, g: 0.28, b: 0.02, a: 0.85 },
    };
  }
  if (cls === "3" || cls === "sign_tower_G") {
    return {
      name: "GREEN",
      color: { r: 0.18, g: 0.95, b: 0.38, a: 1.0 },
      bg: { r: 0.03, g: 0.32, b: 0.1, a: 0.85 },
    };
  }
  if (cls === "0" || cls === "sign_tower") {
    return {
      name: "OFF",
      color: { r: 0.65, g: 0.78, b: 0.95, a: 1.0 },
      bg: { r: 0.12, g: 0.16, b: 0.24, a: 0.85 },
    };
  }
  return {
    name: cls,
    color: { r: 0.8, g: 0.8, b: 0.8, a: 1.0 },
    bg: { r: 0.15, g: 0.15, b: 0.15, a: 0.85 },
  };
}

export default function script(
  event: Input<"/sign_yolo/detections">,
): ImageAnnotations {
  const msg = event.message;
  const stamp = msg.header.stamp;
  const points: PointsAnnotation[] = [];
  const texts: TextAnnotation[] = [];

  for (let i = 0; i < msg.detections.length; i++) {
    const det = msg.detections[i];
    if (!det || det.results.length === 0) {
      continue;
    }
    const hyp = det.results[0]?.hypothesis;
    const cls = hyp?.class_id ?? "";
    const score = hyp?.score ?? 0;
    const cx = det.bbox.center.position.x;
    const cy = det.bbox.center.position.y;
    const hw = det.bbox.size_x * 0.5;
    const hh = det.bbox.size_y * 0.5;
    const x0 = cx - hw;
    const y0 = cy - hh;
    const x1 = cx + hw;
    const y1 = cy + hh;
    const style = lampStyle(cls);

    points.push({
      timestamp: stamp,
      type: PointsAnnotationType.LINE_LOOP,
      points: [
        { x: x0, y: y0 },
        { x: x1, y: y0 },
        { x: x1, y: y1 },
        { x: x0, y: y1 },
      ],
      outline_color: style.color,
      outline_colors: [],
      fill_color: { r: style.color.r, g: style.color.g, b: style.color.b, a: 0.1 },
      thickness: 3,
    });

    texts.push({
      timestamp: stamp,
      position: { x: x0, y: Math.max(18, y0 - 8) },
      text: `${style.name} ${(score * 100).toFixed(0)}%`,
      font_size: 16,
      text_color: style.color,
      background_color: style.bg,
    });
  }

  return { circles: [], points, texts };
}

