import { Input } from "./types.ts";
import {
  SceneUpdate,
  SceneEntity,
  SceneEntityDeletionType,
  Color,
} from "@foxglove/schemas";

export const inputs = ["/sign_yolo/detections"];
export const output = "/sign_yolo/hud_scene";

function mapLamp(cls: string): string {
  if (cls === "0" || cls === "sign_tower") return "OFF";
  if (cls === "1" || cls === "sign_tower_R") return "R";
  if (cls === "2" || cls === "sign_tower_Y") return "Y";
  if (cls === "3" || cls === "sign_tower_G") return "G";
  return "NONE";
}

export default function script(
  event: Input<"/sign_yolo/detections">,
): SceneUpdate {
  const msg = event.message;
  const stamp = event.receiveTime;
  let bestLamp = "NONE";
  let bestScore = 0.5;

  for (let i = 0; i < msg.detections.length; i++) {
    const det = msg.detections[i];
    if (!det) continue;
    for (let j = 0; j < det.results.length; j++) {
      const res = det.results[j];
      if (!res) continue;
      const lamp = mapLamp(res.hypothesis.class_id);
      if (lamp !== "NONE" && res.hypothesis.score >= bestScore) {
        bestScore = res.hypothesis.score;
        bestLamp = lamp;
      }
    }
  }

  const isR = bestLamp === "R";
  const isY = bestLamp === "Y";
  const isG = bestLamp === "G";
  const q = { x: 0, y: 0, z: 0, w: 1 };

  let statusText = "신호등: 미검출";
  let statusColor: Color = { r: 0.6, g: 0.65, b: 0.72, a: 1.0 };
  if (bestLamp === "OFF") {
    statusText = `신호등: OFF 소등 (${(bestScore * 100).toFixed(0)}%)`;
    statusColor = { r: 0.75, g: 0.85, b: 1.0, a: 1.0 };
  } else if (isR) {
    statusText = `신호등: RED (${(bestScore * 100).toFixed(0)}%)`;
    statusColor = { r: 1.0, g: 0.28, b: 0.28, a: 1.0 };
  } else if (isY) {
    statusText = `신호등: YELLOW (${(bestScore * 100).toFixed(0)}%)`;
    statusColor = { r: 1.0, g: 0.9, b: 0.2, a: 1.0 };
  } else if (isG) {
    statusText = `신호등: GREEN (${(bestScore * 100).toFixed(0)}%)`;
    statusColor = { r: 0.2, g: 0.95, b: 0.4, a: 1.0 };
  }

  const rSize = isR ? 0.115 : 0.085;
  const ySize = isY ? 0.115 : 0.085;
  const gSize = isG ? 0.115 : 0.085;

  const entity: SceneEntity = {
    timestamp: stamp,
    frame_id: "base",
    id: "sign_tower",
    lifetime: { sec: 1, nsec: 0 },
    frame_locked: true,
    metadata: [],
    arrows: [],
    cubes: [
      {
        pose: { position: { x: -0.45, y: 0.02, z: 0.36 }, orientation: q },
        size: { x: 0.16, y: 0.09, z: 0.50 },
        color: { r: 0.16, g: 0.18, b: 0.22, a: 0.95 },
      },
      {
        pose: { position: { x: -0.45, y: 0.02, z: 0.10 }, orientation: q },
        size: { x: 0.24, y: 0.16, z: 0.025 },
        color: { r: 0.28, g: 0.31, b: 0.38, a: 0.95 },
      },
    ],
    spheres: [
      {
        pose: { position: { x: -0.45, y: -0.03, z: 0.51 }, orientation: q },
        size: { x: rSize, y: rSize, z: rSize },
        color: isR
          ? { r: 1.0, g: 0.18, b: 0.18, a: 1.0 }
          : { r: 0.45, g: 0.1, b: 0.1, a: 0.28 },
      },
      {
        pose: { position: { x: -0.45, y: -0.03, z: 0.36 }, orientation: q },
        size: { x: ySize, y: ySize, z: ySize },
        color: isY
          ? { r: 1.0, g: 0.88, b: 0.12, a: 1.0 }
          : { r: 0.45, g: 0.38, b: 0.08, a: 0.28 },
      },
      {
        pose: { position: { x: -0.45, y: -0.03, z: 0.21 }, orientation: q },
        size: { x: gSize, y: gSize, z: gSize },
        color: isG
          ? { r: 0.15, g: 0.95, b: 0.35, a: 1.0 }
          : { r: 0.08, g: 0.42, b: 0.15, a: 0.28 },
      },
    ],
    cylinders: [],
    lines: [],
    triangles: [],
    texts: [
      {
        pose: { position: { x: -0.45, y: 0.0, z: 0.67 }, orientation: q },
        billboard: true,
        font_size: 15,
        scale_invariant: true,
        color: statusColor,
        text: statusText,
      },
    ],
    models: [],
  };

  return {
    deletions: [
      {
        timestamp: stamp,
        type: SceneEntityDeletionType.ALL,
        id: "",
      },
    ],
    entities: [entity],
  };
}

