import { Input } from "./types.ts";
import {
  SceneUpdate,
  SceneEntity,
  SceneEntityDeletionType,
  CubePrimitive,
  TextPrimitive,
  Color,
} from "@foxglove/schemas";

export const inputs = ["/read_sign_barcode/_action/feedback"];
export const output = "/sign_barcode/hud_scene";

function slotColor(ch: string): Color {
  if (ch === "R") return { r: 1.0, g: 0.22, b: 0.22, a: 0.95 };
  if (ch === "Y") return { r: 1.0, g: 0.88, b: 0.15, a: 0.95 };
  if (ch === "G") return { r: 0.18, g: 0.95, b: 0.38, a: 0.95 };
  return { r: 0.22, g: 0.25, b: 0.32, a: 0.65 };
}

export default function script(
  event: Input<"/read_sign_barcode/_action/feedback">,
): SceneUpdate {
  const raw: any = event.message;
  const fb = raw.feedback ?? raw;
  const seq: string = fb.sequence ?? "";
  const barcode: string = fb.barcode ?? "";
  const stamp = event.receiveTime;
  const q = { x: 0, y: 0, z: 0, w: 1 };

  const cubes: CubePrimitive[] = [];
  const texts: TextPrimitive[] = [];

  let rCnt = 0;
  let yCnt = 0;
  let gCnt = 0;
  for (let i = 0; i < seq.length; i++) {
    if (seq[i] === "R") rCnt++;
    else if (seq[i] === "Y") yCnt++;
    else if (seq[i] === "G") gCnt++;
  }

  for (let i = 0; i < 12; i++) {
    const ch = i < seq.length ? (seq[i] ?? "-") : "-";
    const x = -0.22 + i * 0.068;
    const c = slotColor(ch);
    cubes.push({
      pose: { position: { x, y: 0.0, z: 0.35 }, orientation: q },
      size: { x: 0.054, y: 0.04, z: 0.08 },
      color: c,
    });
    texts.push({
      pose: { position: { x, y: -0.03, z: 0.43 }, orientation: q },
      billboard: true,
      font_size: 13,
      scale_invariant: true,
      color: ch === "-" ? { r: 0.55, g: 0.6, b: 0.68, a: 1.0 } : c,
      text: `${i + 1}:${ch}`,
    });
  }

  let bcText = "바코드: 해독 대기 중...";
  let bcColor: Color = { r: 0.7, g: 0.76, b: 0.85, a: 1.0 };
  if (barcode === "P2-01" || barcode === "P2-03") {
    bcText = `바코드: ${barcode}  [오름차순 · 적은 횟수부터]`;
    bcColor = { r: 0.25, g: 0.92, b: 1.0, a: 1.0 };
  } else if (barcode === "P2-02" || barcode === "P2-04") {
    bcText = `바코드: ${barcode}  [내림차순 · 많은 횟수부터]`;
    bcColor = { r: 1.0, g: 0.72, b: 0.25, a: 1.0 };
  } else if (barcode.length > 0) {
    bcText = `바코드: ${barcode}`;
    bcColor = { r: 1.0, g: 0.4, b: 0.4, a: 1.0 };
  }

  cubes.push({
    pose: { position: { x: 0.15, y: 0.02, z: 0.56 }, orientation: q },
    size: { x: 0.78, y: 0.03, z: 0.09 },
    color: { r: 0.14, g: 0.2, b: 0.28, a: 0.9 },
  });

  texts.push({
    pose: { position: { x: 0.15, y: -0.02, z: 0.56 }, orientation: q },
    billboard: true,
    font_size: 16,
    scale_invariant: true,
    color: bcColor,
    text: bcText,
  });

  texts.push({
    pose: { position: { x: 0.15, y: 0.0, z: 0.20 }, orientation: q },
    billboard: true,
    font_size: 15,
    scale_invariant: true,
    color: { r: 0.92, g: 0.95, b: 1.0, a: 1.0 },
    text: `점멸 기록: ${seq.length}/12   |   R: ${rCnt}   Y: ${yCnt}   G: ${gCnt}`,
  });

  const entity: SceneEntity = {
    timestamp: stamp,
    frame_id: "base",
    id: "sign_feedback_hud",
    lifetime: { sec: 0, nsec: 0 },
    frame_locked: true,
    metadata: [],
    arrows: [],
    cubes,
    spheres: [],
    cylinders: [],
    lines: [],
    triangles: [],
    texts,
    models: [],
  };

  return {
    deletions: [
      {
        timestamp: stamp,
        type: SceneEntityDeletionType.ALL,
        id: "",
      },
    ],
    entities: [entity],
  };
}
